def f(inputs: List[Tuple[List[int], List[int]]]) -> int:
    results = []
    for num_set in inputs:
        num_set1, num_set2 = num_set
        cnt = 0
        for num1, num2 in zip(num_set1, num_set2):
            if num1 == num2:
                cnt += 1
        results.append(cnt)
